 document.addEventListener('submit',e=>{if(e.target.id!=='shipping-form')return;e.preventDefault();if(modal?.type!=='shipping')return;const data={...shippingDraft(),method:modal.method},result=D.validateShipping(data);if(!result.valid){modal.draft=data;modal.errors=result.errors;renderModal();dialog.querySelector('[aria-invalid="true"]')?.focus();return;}if(state.shipments.some(o=>o.target===modal.id))return;const p=plot(modal.id)||animal(modal.id),s={id:'HS-'+String(state.shipments.length+1).padStart(4,'0'),target:p.id,name:animal(p.id)?p.output:p.name,method:modal.method,recipient:D.maskShipping(data),step:0};state.shipments.push(s);addLog(`${p.id} 已预约${animal(p.id)?'出栏处理':'采收'}与${s.method==='pickup'?'自提':'配送'}`);render();open('shipping-ok');});
 document.addEventListener('change',e=>{if(e.target.id==='recommend-month'){state.month=Number(e.target.value);render();$('#recommend-month')?.focus({preventScroll:true});}});
 dialog.addEventListener('cancel',e=>{e.preventDefault();close();});
 dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
 window.addEventListener('popstate',()=>{state.view=routes.includes(location.hash.slice(1))?location.hash.slice(1):'farm';if(dialog.open)close();render();});
 render();
